package org.sonatype.nexus.repository.openformats.gitlfs;
@org.springframework.stereotype.Component @org.springframework.context.annotation.Scope("prototype") @org.springframework.beans.factory.annotation.Qualifier("gitlfs") public class GitlfsContent extends org.sonatype.nexus.repository.openformats.OpenContentFacet { public GitlfsContent(@org.springframework.beans.factory.annotation.Qualifier("gitlfs") org.sonatype.nexus.repository.content.store.FormatStoreManager store) { super(store); } @Override protected String determineContentType(org.sonatype.nexus.repository.content.Asset asset,org.sonatype.nexus.blobstore.api.Blob blob,boolean strict) { return "LFS_OBJECT".equals(asset.kind())?"application/octet-stream":super.determineContentType(asset,blob,strict); } }
